var body = $input.first().json;
var msg = body["message"] || body["edited_message"];
if (!msg) return [{json:{skip:true}}];
var chat = msg["chat"] || {};
var senderId = "" + chat["id"];
var text = (msg["text"] || "").trim();
var lower = text.toLowerCase();

var command = "help";
var cancelTarget = "";

if (lower === "today" || lower.indexOf("ဒီနေ့") >= 0 || lower === "1") {
  command = "today";
} else if (lower === "tomorrow" || lower.indexOf("မနက်ဖြန်") >= 0 || lower === "2") {
  command = "tomorrow";
} else if (lower === "all" || lower.indexOf("အားလုံး") >= 0 || lower === "3") {
  command = "all";
} else if (lower.indexOf("cancel ") === 0) {
  command = "cancel";
  cancelTarget = text.substring(7).trim();
} else if (lower.indexOf("ပယ်ဖျက် ") === 0) {
  command = "cancel";
  cancelTarget = text.substring(9).trim();
} else {
  command = "help";
}

return [{json:{senderId:senderId, command:command, cancelTarget:cancelTarget, rawText:text}}];

var cmdData = $('Parse Doctor Command').first().json;
var command = cmdData["command"];
var cancelTarget = (cmdData["cancelTarget"] || "").toLowerCase();
var senderId = cmdData["senderId"];

var appts = [];
var allItems = $input.all();
for (var i = 0; i < allItems.length; i++) {
  var item = allItems[i].json;
  if (item["appointment_datetime"]) { appts.push(item); }
}

var today = new Date();
var todayStr = today.toISOString().split("T")[0];
var tmr = new Date(today); tmr.setDate(today.getDate()+1);
var tmrStr = tmr.toISOString().split("T")[0];

var replyText = "";
var needsUpdate = false;
var updatePatientName = "";
var updateDatetime = "";

if (command === "help") {
  replyText = "Doctor Bot Commands:\n\n1 or 'today' — Today appts\n2 or 'tomorrow' — Tomorrow appts\n3 or 'all' — All upcoming appts\n'cancel NAME' — Cancel appointment\n\nExample:\ncancel Ko Aung";
}
else if (command === "today" || command === "tomorrow" || command === "all") {
  var filtered = [];
  for (var i = 0; i < appts.length; i++) {
    var a = appts[i];
    var dt = (a["appointment_datetime"] || "").split("T")[0];
    var status = (a["status"] || "").toLowerCase();
    if (status === "cancelled") continue;
    if (command === "today" && dt === todayStr) { filtered.push(a); }
    else if (command === "tomorrow" && dt === tmrStr) { filtered.push(a); }
    else if (command === "all") { filtered.push(a); }
  }
  if (filtered.length === 0) {
    var dayWord = command === "today" ? "ဒီနေ့" : command === "tomorrow" ? "မနက်ဖြန်" : "Upcoming";
    replyText = dayWord + " appointment မရှိပါ";
  } else {
    var lines = [];
    for (var i = 0; i < filtered.length; i++) {
      var a = filtered[i];
      var dtParts = (a["appointment_datetime"] || "").split("T");
      var datePart = dtParts[0] || "";
      var timePart = dtParts.length > 1 ? dtParts[1].substring(0,5) : "";
      var line = (i+1) + ". " + (a["patient_name"] || "?");
      if (command === "all") { line += " (" + datePart + ")"; }
      line += " — " + timePart + " | " + (a["reason"] || "");
      lines.push(line);
    }
    var header = command === "today" ? "Today Appointments" : command === "tomorrow" ? "Tomorrow Appointments" : "All Upcoming Appointments";
    replyText = header + " (" + filtered.length + "):\n\n" + lines.join("\n");
  }
}
else if (command === "cancel") {
  if (!cancelTarget) {
    replyText = "Usage: cancel NAME\nExample: cancel Ko Aung";
  } else {
    var found = null;
    for (var i = 0; i < appts.length; i++) {
      var a = appts[i];
      var name = (a["patient_name"] || "").toLowerCase();
      var status = (a["status"] || "").toLowerCase();
      if (status === "cancelled") continue;
      if (name.indexOf(cancelTarget) >= 0) { found = a; break; }
    }
    if (!found) {
      replyText = "'" + cancelTarget + "' မတွေ့ပါ\n\nPatient name မှန်မမှန် စစ်ပါ";
    } else {
      needsUpdate = true;
      updatePatientName = found["patient_name"];
      updateDatetime = found["appointment_datetime"];
      replyText = "Cancelled: " + found["patient_name"] + "\nSlot: " + (found["slot"] || found["appointment_datetime"]);
    }
  }
}

return [{json:{
  senderId: senderId,
  command: command,
  replyText: replyText,
  needsUpdate: needsUpdate,
  updatePatientName: updatePatientName,
  updateDatetime: updateDatetime
}}];
